def L(w1, w2):
    return (w1 - 3) ** 2 + 2 * (w2 - 1) ** 2

for w1 in [1.0, 1.5, 2.0]:
    print(w1, L(w1, 3))   # the loss falls as w1 rises

def dL_dw1(w1, w2):
    return 2 * (w1 - 3)   # the w2 part is a constant here

print(dL_dw1(1, 3))   # -4

def L(w1, w2):
    return (w1 - 3) ** 2 + 2 * (w2 - 1) ** 2

for w2 in [3.0, 2.5, 2.0]:
    print(w2, L(1, w2))   # the loss falls as w2 falls

def dL_dw2(w1, w2):
    return 4 * (w2 - 1)   # the w1 part is a constant here

print(dL_dw2(1, 3))   # 8
